import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/getting-started.md","filePath":"user-guide/getting-started.md","lastUpdated":1787586465000}'),n={name:"user-guide/getting-started.md"};function i(s,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to Lertaro! Lertaro is an ultra-fast file search launcher and productivity tool purpose-built for Windows. This guide walks you through installation options, core architecture, three distinct window modes, and essential search workflows.</p><h2 id="_1-download-installation" tabindex="-1">1. Download &amp; Installation <a class="header-anchor" href="#_1-download-installation" aria-label="Permalink to &quot;1. Download &amp; Installation&quot;">​</a></h2><p>You can get the latest release from the official homepage. Each release provides two execution formats, compiled natively for both <strong>x64</strong> and <strong>ARM64</strong>:</p><h3 id="installer-lertaro-setup-exe-recommended" tabindex="-1">Installer (<code>Lertaro-Setup.exe</code>, Recommended) <a class="header-anchor" href="#installer-lertaro-setup-exe-recommended" aria-label="Permalink to &quot;Installer (`Lertaro-Setup.exe`, Recommended)&quot;">​</a></h3><ul><li><strong>Automated Configuration</strong>: The setup wizard automatically registers the background indexing service (<code>Lertaro.Service</code>), configures startup entries, and installs required .NET desktop runtime components.</li><li><strong>Seamless Upgrades</strong>: Supports background update checks and one-click in-place upgrades.</li></ul><h3 id="portable-edition-lertaro-portable-zip" tabindex="-1">Portable Edition (<code>Lertaro-Portable.zip</code>) <a class="header-anchor" href="#portable-edition-lertaro-portable-zip" aria-label="Permalink to &quot;Portable Edition (`Lertaro-Portable.zip`)&quot;">​</a></h3><ul><li><strong>Extract and Run</strong>: Unzip to any folder and run immediately without installation.</li><li><strong>Runtime Dependency</strong>: If your system lacks the required .NET desktop runtime, run the bundled <code>install-dotnet-runtime.bat</code> script once.</li><li><strong>Self-Contained Data Storage</strong>: The portable edition saves machine-wide data to <code>Data\\Machine</code> alongside the application, and user settings to <code>Data\\Users\\&lt;SID hash&gt;</code>. If the <code>Data</code> directory does not exist yet, it falls back to <code>%ProgramData%\\Lertaro</code> and <code>%LocalAppData%\\Lertaro</code> for compatibility; once created, it prioritizes local data as a fully self-contained instance.</li><li><strong>Clean Removal</strong>: Before deleting the portable folder, run the bundled <code>portable-cleanup.bat</code> script. It stops and uninstalls the background service, and removes current-user <code>lertaro://</code> URI registrations and startup entries.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If you are using a Windows on ARM device (such as Surface Pro X or Snapdragon laptops), download the native <code>Lertaro-Setup-arm64.exe</code> or <code>Lertaro-Portable-arm64.zip</code> for maximum performance and battery efficiency.</p></div><h2 id="_2-architecture-overview" tabindex="-1">2. Architecture Overview <a class="header-anchor" href="#_2-architecture-overview" aria-label="Permalink to &quot;2. Architecture Overview&quot;">​</a></h2><p>When running Lertaro for the first time, it installs and launches a dedicated Windows service (<code>Lertaro.Service</code>). Understanding this separation helps you get the most out of the system:</p><ul><li><strong>Foreground App (UI &amp; Interaction)</strong>: Renders search windows, floating panels, action menus, keyboard hooks, and interactive previews. The foreground process maintains a minimal memory footprint and instant responsiveness.</li><li><strong>Background Service (Indexing &amp; Data)</strong>: Runs with service privileges in the background, continuously monitoring NTFS / ReFS USN change journals, tracking filesystem events, managing network drives, and maintaining an in-memory index tree.</li><li><strong>Architectural Benefits</strong>: Restarting, updating, or closing the UI never loses the background index or triggers full rescans. Heavy indexing tasks never stutter your keystrokes. You can check service status and health at any time under <a href="./settings/service-status.html"><strong>Settings → Service Status</strong></a>.</li></ul><h2 id="_3-three-window-modes" tabindex="-1">3. Three Window Modes <a class="header-anchor" href="#_3-three-window-modes" aria-label="Permalink to &quot;3. Three Window Modes&quot;">​</a></h2><p>Lertaro is not limited to a single search window. It adapts to different workflows with three purpose-built window modes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Window Mode</th><th style="text-align:left;">Default Trigger</th><th style="text-align:left;">Key Features &amp; Design Focus</th><th style="text-align:left;">Best Used For</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Quick Window</strong></td><td style="text-align:left;">Double-tap <code>Ctrl</code> (Customizable)</td><td style="text-align:left;">Compact centered floating bar, optimized for muscle memory, number key jumps, and pure keyboard navigation</td><td style="text-align:left;">Frequent app launching, quick calculations, translations, and fast file lookup</td></tr><tr><td style="text-align:left;"><strong>Full Window</strong></td><td style="text-align:left;">Taskbar/Start shortcut, or <code>Ctrl+F</code></td><td style="text-align:left;">Full-featured large window with tabular results, sidebar filter groups, column sorting, and built-in Space Analyzer</td><td style="text-align:left;">Deep file browsing, broad exploration, disk space cleaning, and batch management</td></tr><tr><td style="text-align:left;"><strong>Inline Window</strong></td><td style="text-align:left;">Automatically docks in file dialogs or Explorer</td><td style="text-align:left;">Embedded seamlessly into standard Windows file dialogs or third-party file managers</td><td style="text-align:left;">Quick destination locating when opening or saving files in external software</td></tr></tbody></table><p>All three window modes share the exact same underlying search engine, shortcut scheme, filter rules, and action menus.</p><h2 id="_4-first-search-basic-navigation" tabindex="-1">4. First Search &amp; Basic Navigation <a class="header-anchor" href="#_4-first-search-basic-navigation" aria-label="Permalink to &quot;4. First Search &amp; Basic Navigation&quot;">​</a></h2><h3 id="type-to-search" tabindex="-1">Type to Search <a class="header-anchor" href="#type-to-search" aria-label="Permalink to &quot;Type to Search&quot;">​</a></h3><p>Simply open the search window and start typing. Results appear in real time (sub-millisecond latency). Search matching uses fuzzy jump matching by default — characters do not need to be contiguous. For advanced syntax, operators, and modifiers, see <a href="./search-syntax.html"><strong>Search Syntax</strong></a>.</p><h3 id="navigating-opening-results" tabindex="-1">Navigating &amp; Opening Results <a class="header-anchor" href="#navigating-opening-results" aria-label="Permalink to &quot;Navigating &amp; Opening Results&quot;">​</a></h3><ul><li><strong>Move Selection</strong>: Use arrow keys <code>↑</code> / <code>↓</code> (or configured navigation hotkeys <code>Ctrl+P</code> / <code>Ctrl+N</code>) to move selection up and down.</li><li><strong>Open Directly</strong>: Press <code>Enter</code> to open the highlighted file or launch the application.</li><li><strong>Reveal in Explorer</strong>: Press <code>Ctrl+Enter</code> to locate and select the item directly in Windows File Explorer.</li><li><strong>Run as Administrator</strong>: Press <code>Ctrl+Shift+Enter</code> to launch the selected application with administrative privileges.</li><li><strong>Direct Number Jump</strong>: In the Quick Window, press <code>Ctrl</code> + <code>1</code>–<code>9</code> to jump directly to any of the first 9 results.</li></ul><h3 id="action-menu-context-actions" tabindex="-1">Action Menu &amp; Context Actions <a class="header-anchor" href="#action-menu-context-actions" aria-label="Permalink to &quot;Action Menu &amp; Context Actions&quot;">​</a></h3><p>Press <code>Ctrl+O</code> or <code>→</code> on any highlighted item to expand the comprehensive <strong>Action Menu</strong>, offering path copying, file operations, properties, and plugin extensions. Read <a href="./actions-and-preview.html"><strong>Actions &amp; Preview</strong></a> and <a href="./hotkeys.html"><strong>Hotkeys</strong></a> for more tips.</p>',23)])])}const p=t(n,[["render",i]]);export{h as __pageData,p as default};
